namespace ChkobbaMaui.Models; public enum Suit { Coins, Cups, Swords, Clubs } public sealed record Card(Suit Suit, int Rank) { public string RankLabel => Rank switch { 1 => "A", 8 => "J", 9 => "Q", 10 => "K", _ => Rank.ToString() }; public string SuitSymbol => Suit switch { Suit.Coins => "🪙", Suit.Cups => "🏆", Suit.Swords => "⚔️", _ => "♣" }; public string Display => $"{RankLabel}\n{SuitSymbol}"; public int CaptureValue => Rank; }